/// Общие советы по деньгам (D97): ориентиры финансовой грамотности, которые
/// показывает карточка «Совет дня» в приложении и строка «💡 Совет» в утренней
/// сводке бота. Лежат в ядре, чтобы текст был один для обоих.
///
/// 72 коротких совета на русском и казахском. Общие идеи, а не выводы о
/// личных финансах: без обязательных процентов и обещаний результата.
/// Границы те же, что у консультанта (D84): без инвестиций, кредитов, банков
/// и налогов; без учётных терминов (D36). Казахские тексты написаны без
/// носителя — вычитать.
library;

class MoneyTip {
  const MoneyTip(this.id, {required this.ru, required this.kk});

  /// Устойчивый код — для тестов и журнала, не для показа.
  final String id;
  final String ru;
  final String kk;

  String text(String locale) => locale == 'kk' ? kk : ru;
}

