/// Совет на день для сводки: один на всех, меняется каждый день, по кругу.
MoneyTip moneyTipOfDay(DateTime day) {
  final n = DateTime.utc(day.year, day.month, day.day).difference(DateTime.utc(2026, 1, 1)).inDays;
  return moneyTips[((n % moneyTips.length) + moneyTips.length) % moneyTips.length];
}
